/*
 * NETWORK_$READ_AHEAD - Page a run of pages in from a remote node
 *
 * Original address: 0x00E0FC08 (SAU2 map: NETWORK, NETWORK_$READ_AHEAD at E0FC08)
 * Size: 1628 bytes (0x00E0FC08 .. 0x00E10263); its crash status cell
 * follows at 0x00E10268.
 * Generated by: Claude Opus 5.5
 *
 * Called by the AST paging code (0x00E02D7E, 0x00E036F0, 0x00E03D28,
 * 0x00E04218).  Asks the node in `net_info` for the pages
 * req->page_num .. req->page_num + count - 1 of the object in `req` with
 * page-in requests (type 0xC) on a fresh socket, and collects the reply
 * packets (type 0xD, one page of data each) into physical pages whose
 * numbers go to ppn_array.  Returns the number of pages delivered.
 *
 * Frame (link.w A6,-0x174; D2-D7/A2-A5 saved; A5 = 0xE248FC, the NETWORK
 * data):
 *   (0x08,A6) net_info   {network, node} (A4)
 *   (0x0C,A6) req        32-byte IN/OUT record
 *   (0x10,A6) ppn_array  (A3, advanced per delivered page)
 *   (0x14,A6) page_size  word, the M$DIU$LLW divisor
 *   (0x16,A6) count      word
 *   (0x18,A6) flag_18    byte, copied into the request
 *   (0x1A,A6) flag_1a    byte, copied into the request; FALSE makes an
 *                        end-of-object status zero-fill the partial page
 *   (0x1C,A6) dtm, (0x20,A6) clock, (0x24,A6) acl_info  6-byte clocks
 *   (0x28,A6) status
 *   locals: see the comments on each; D6 pages delivered, D4 bytes already
 *   in the current partial page, D5 its physical address, D7 retries.
 *
 * Blocks:
 *   0x00E0FC1E-0x00E0FC38  clear dtm->high; paging service must be allowed
 *   0x00E0FC3C-0x00E0FCE0  allocate a socket, set up the request and limits
 *   0x00E0FCE4-0x00E0FD9C  per request: new packet id, donate the extra
 *                          buffer pages the reply may need to NETBUF
 *   0x00E0FDA0-0x00E0FE5C  send, wait; on timeout retry (forever for the
 *                          mother node)
 *   0x00E0FE60-0x00E0FF2A  validate the reply packet and its checksum
 *   0x00E0FF32-0x00E0FF82  first reply: status, clocks and record out
 *   0x00E0FF86-0x00E1008A  deliver the packet's data pages (whole pages go
 *                          straight to ppn_array; a partial page is copied
 *                          into the page being filled)
 *   0x00E1008C-0x00E10192  error statuses: end-of-object zero fill, and
 *                          0x50008 (pages not on disk) zero pages
 *   0x00E10194-0x00E101C4  a reply packet of the wrong kind
 *   0x00E101D4-0x00E10262  take the donated pages back, release a partial
 *                          page, close the socket, update the counters
 *
 * Quirks reproduced:
 *   - A failed SOCK_$ALLOCATE and a data length that is over a page but not
 *     a whole number of pages call CRASH_SYSTEM with the cell at 0x00E0F9FC
 *     (0x00110005); a checksum mismatch calls it with 0x00E10268
 *     (0x00110010).  The code after each call runs as if it returned.
 *   - network_$page_chksum is pushed a second argument (&resp_len) it never
 *     reads.
 *   - dtm->high is cleared at entry even when the call fails.
 *   - A partially filled last page is handed back to NETBUF at exit
 *     (0x00E10204) and is not counted.
 */

#include "network/network_internal.h"
#include "sock/sock.h"
#include "pkt/pkt.h"
#include "math/math.h"
#include "wp/wp.h"
#include "netbuf/netbuf.h"
#include "mmap/mmap.h"
#include "route/route.h"
#include "misc/crash_system.h"
#include "ast/ast.h"          /* status_$ast_eof */

/* Request / reply packet types (0x00E0FCEE, 0x00E0FEA2) */
#define NETWORK_PAGIN_RQST          0x000C
#define NETWORK_PAGIN_REPLY         0x000D
#define NETWORK_PAGIN_VERSION       8
#define NETWORK_PAGIN_RQST_LEN      0x2E

/* Pages per request: 0x20 on the local network, 8 across a router */
#define NETWORK_PAGIN_LIMIT_LOCAL   0x20
#define NETWORK_PAGIN_LIMIT_REMOTE  8

/* Reply version that carries the three clocks: `cmpi.w #0x7` 0x00E0FF40 */
#define NETWORK_PAGIN_CLOCK_VERSION 7

/* SOCK_$ALLOCATE limits: `move.l #0x200000` / `pea (0x400).w` */
#define NETWORK_PAGIN_SOCK_PAGES    0x200000
#define NETWORK_PAGIN_SOCK_QUEUE    0x400

/* "pages not on disk" reply status: `cmpi.l #0x50008` (0x00E0FED0) */
#define NETWORK_PAGIN_ST_NULL_PAGES 0x00050008

/*
 * The crash status cells.  0x00E0F9FC (00 11 00 05) lies at the end of the
 * code before NETWORK_$GET_PKT_SIZE and is reached PC-relative from
 * 0x00E0FC58, 0x00E0FFA2 and 0x00E10010; 0x00E10268 (00 11 00 10) follows
 * this routine and is reached from 0x00E0FEF4.
 */
static const status_$t network_$read_ahead_crash_status =
    status_$network_receive_process_failed_to_start;     /* 0x00E0F9FC */
static const status_$t network_$read_ahead_chksum_status =
    status_$network_bad_checksum;                         /* 0x00E10268 */

int16_t NETWORK_$READ_AHEAD(void *net_info, void *uid, uint32_t *ppn_array,
                            uint16_t page_size, int16_t count,
                            int8_t no_read_ahead, uint8_t flags,
                            clock_t *dtm, clock_t *clock,
                            clock_t *acl_info, status_$t *status)
{
    uint32_t *net = (uint32_t *)net_info;                 /* A4 */
    network_$page_request_t *req = (network_$page_request_t *)uid;
    int8_t flag_18 = no_read_ahead;                       /* (0x18,A6) */
    int8_t flag_1a = (int8_t)flags;                       /* (0x1A,A6) */
    uint32_t data_bufs[4];                                /* (-0x10,A6) */
    network_$pagin_reply_t resp;                          /* (-0xC8,A6) */
    network_$pagin_rqst_t rqst;                           /* (-0x110,A6) */
    uint32_t chksum;                                      /* (-0x114,A6) */
    uint32_t calloc_ppn;                                  /* (-0x118,A6) */
    uint32_t dat;                                         /* (-0x11C,A6) */
    uint32_t src;                                         /* (-0x120,A6) */
    status_$t st;                                         /* (-0x124,A6) */
    uint32_t end;                                         /* (-0x12C,A6) */
    uint32_t start;                                       /* (-0x130,A6) */
    int32_t ec_value;                                     /* (-0x134,A6) */
    int16_t donated;                                      /* (-0x138,A6) */
    int16_t zero_len;                                     /* (-0x13A,A6) */
    int16_t bufs_used;                                    /* (-0x13C,A6) */
    int16_t seq;                                          /* (-0x144,A6) */
    int16_t timeout;                                      /* (-0x148,A6) */
    uint16_t retry_max;                                   /* (-0x14A,A6) */
    int16_t limit;                                        /* (-0x14C,A6) */
    uint16_t data_len;                                    /* (-0x14E,A6) */
    int16_t resp_len;                                     /* (-0x150,A6) */
    int16_t pkt_id;                                       /* (-0x152,A6) */
    uint16_t sock;                                        /* (-0x154,A6) */
    int8_t hdr_done;                                      /* (-0x15A,A6) */
    int32_t wanted;                                       /* (-0x160,A6) */
    int32_t len;                                          /* (-0x170,A6) */
    int16_t done;                                         /* D6 */
    int16_t partial;                                      /* D4 */
    uint32_t dst;                                         /* D5 */
    int16_t retries;                                      /* D7 */
    int32_t need;                                         /* D0 / D3 */
    int32_t remain;                                       /* D2 */
    int32_t zero_bytes;                                   /* D3 */
    int32_t chunk;                                        /* D2 */
    uint32_t *out;                                        /* A3 */
    int buf;                                              /* A2 cursor */
    int16_t n;

    /* 0x00E0FC1E-0x00E0FC38 */
    dtm->high = 0;
    if ((NETWORK_$SERVICE_FLAGS & NETWORK_SERVICE_PAGING) == 0) {
        *status = status_$network_request_denied_by_local_node;
        return 0;
    }

    /* 0x00E0FC3C-0x00E0FC62 */
    if (SOCK_$ALLOCATE(&sock, NETWORK_PAGIN_SOCK_PAGES, NETWORK_PAGIN_SOCK_QUEUE) >= 0) {
        CRASH_SYSTEM(&network_$read_ahead_crash_status);
    }

    /* 0x00E0FC64-0x00E0FCE0 */
    donated = 0;
    done = 0;
    hdr_done = 0;
    partial = done;
    dst = 0;              /* D5 and (-0x124,A6) are not initialised by the */
    st = status_$ok;      /* image; neither is read before it is written   */
    if (net[0] == 0 || net[0] == ROUTE_$PORT) {
        limit = NETWORK_PAGIN_LIMIT_LOCAL;
    } else {
        limit = NETWORK_PAGIN_LIMIT_REMOTE;
    }
    rqst.req = *req;
    start = req->page_num;
    wanted = (int32_t)count;
    end = (uint32_t)wanted + start;
    out = ppn_array;

    while (start < end) {                                 /* 0x00E101C6 */
        /* 0x00E0FCE4-0x00E0FD1A: the request */
        pkt_id = PKT_$NEXT_ID();
        rqst.type = NETWORK_PAGIN_RQST;
        rqst.version = NETWORK_PAGIN_VERSION;
        rqst.page_size = 0x400;
        rqst.limit = limit;
        rqst.req.page_num = start;
        rqst.flag_1a = flag_1a;
        rqst.count = (uint16_t)((uint16_t)end - (uint16_t)start);
        rqst.flag_18 = flag_18;
        seq = 1;

        /* 0x00E0FD26-0x00E0FD9C: donate the buffers the reply may need */
        retries = 0;
        len = (int32_t)done;
        need = (int32_t)M$DIU$LLW((((end - start) << 10) + (uint32_t)page_size) - 1,
                                  page_size);
        if (need > (int32_t)limit) {
            need = (int32_t)limit;
        }
        need -= wanted - len;
        if (need < 0) {
            need = 0;
        }
        while ((int16_t)need > donated) {
            WP_$CALLOC(&calloc_ppn, &st);
            NETBUF_$RTN_DAT(calloc_ppn << 10);
            donated++;
        }

    resend:
        /* 0x00E0FDA0-0x00E0FDDE */
        ec_value = SOCK_$DATA.socket_ptr[(int16_t)sock]->ec.value + 1;
        network_$send_request(net, (int16_t)sock, pkt_id, (int16_t *)(void *)&rqst,
                              NETWORK_PAGIN_RQST_LEN, 0, 0, &retry_max,
                              &timeout, &st);
        if (st != status_$ok) {
            goto finish;
        }

    wait:
        /* 0x00E0FDE2-0x00E0FE24 */
        if (!(start < end)) {
            goto finish;
        }
        if (network_$wait_response((int16_t)sock, pkt_id,
                                   (uint16_t)(timeout + NETWORK_$SERVICE_TIME),
                                   &ec_value, (int16_t *)(void *)&resp,
                                   &resp_len, data_bufs, &data_len) >= 0) {
            /* 0x00E0FE26-0x00E0FE5C: no reply in time */
            retries++;
            if (done > 0) {
                goto finish;
            }
            if ((int32_t)retries > (int32_t)(uint32_t)retry_max &&
                net[1] != NETWORK_$MOTHER_NODE) {
                st = status_$network_remote_node_failed_to_respond;
                goto finish;
            }
            if (seq > 1) {
                continue;                                 /* to 0x00E101C6 */
            }
            goto resend;
        }

        /* 0x00E0FE60-0x00E0FE9E: data must be whole kilobytes */
        bufs_used = 0;
        remain = (int32_t)(uint32_t)data_len;
        len = remain;
        if ((data_len & 0x3FF) != 0) {
            PKT_$DUMP_DATA(data_bufs, (int16_t)data_len);
            retries++;
            if ((int32_t)retries <= (int32_t)(uint32_t)retry_max) {
                goto resend;
            }
            st = status_$network_data_length_too_large;
            goto finish;
        }

        /* 0x00E0FEA2-0x00E0FEB4 */
        if (resp.type != NETWORK_PAGIN_REPLY || resp.seq != seq) {
            goto wrong_reply;
        }
        st = resp.status;

        /* 0x00E0FEBE-0x00E0FF2A: the optional data checksum */
        if (resp.chksum != 0 && NETWORK_$DO_CHKSUM < 0 &&
            (st == status_$ok || st == NETWORK_PAGIN_ST_NULL_PAGES)) {
            chksum = network_$page_chksum(data_bufs);
            if (chksum != resp.chksum) {
                CRASH_SYSTEM(&network_$read_ahead_chksum_status);
                PKT_$DUMP_DATA(data_bufs, (int16_t)data_len);
                data_bufs[0] = 0;
                NETWORK_$BAD_CHKSUM_CNT++;
                retries++;
                if ((int32_t)retries <= (int32_t)(uint32_t)retry_max) {
                    goto resend;
                }
                st = status_$network_too_many_transmit_retries;
            }
        }

        /* 0x00E0FF32-0x00E0FF82: the first reply fills in the outputs */
        if (hdr_done >= 0) {
            *status = st;
            if (resp.version >= NETWORK_PAGIN_CLOCK_VERSION) {
                clock->high = resp.clock_high;
                clock->low = resp.clock_low;
                acl_info->high = resp.acl_high;
                acl_info->low = resp.acl_low;
                dtm->high = resp.dtm_high;
                dtm->low = resp.dtm_low;
            }
            *req = resp.req;
            hdr_done = (int8_t)0xFF;
        }

        /* 0x00E0FF86-0x00E0FFAC */
        if (remain > 0x400 && M$OIS$WLW((long)remain, 0x400) != 0) {
            CRASH_SYSTEM(&network_$read_ahead_crash_status);
        }

        /* 0x00E0FFAE-0x00E0FFC4 */
        if (!(st == status_$ok ||
              (st == NETWORK_PAGIN_ST_NULL_PAGES && resp.version == 1))) {
            goto error_status;
        }

        /* 0x00E0FFC8-0x00E1005A: deliver the data pages */
        buf = 0;
        while (remain > 0) {
            if (partial == 0) {
                bufs_used++;
                dst = data_bufs[buf++];
                *out = dst >> 10;
                if (remain >= 0x400) {
                    done++;
                    out++;
                    remain -= 0x400;
                    continue;
                }
                partial = (int16_t)remain;                /* 0x00E0FFFA */
                dst += (uint32_t)remain;
                remain = 0;
                continue;
            }
            if (0x400 - (int32_t)partial < remain) {      /* 0x00E10000 */
                CRASH_SYSTEM(&network_$read_ahead_crash_status);
                continue;
            }
            bufs_used++;
            src = data_bufs[buf++];
            network_$phys_copy(dst, src, (int16_t)remain);
            NETBUF_$RTN_DAT(src);
            partial = (int16_t)(partial + (int16_t)remain);
            if (partial < 0x400) {
                dst += (uint32_t)remain;
            } else {
                partial = 0;
                done++;
                out++;
            }
            remain = 0;
        }

        /* 0x00E1005E-0x00E10088 */
        seq++;
        start += (uint32_t)len >> 10;
        if (seq <= resp.page_cnt) {
            goto wait;
        }
        if (resp.more >= 0 || done <= 0) {
            continue;
        }
        goto finish;

    error_status:
        /* 0x00E1008C-0x00E100AC */
        if (st != NETWORK_PAGIN_ST_NULL_PAGES) {
            if ((int8_t)((st == status_$ast_eof ? 0xFF : 0) & ~(uint8_t)flag_1a) >= 0) {
                goto finish;
            }
            if (partial <= 0) {
                goto finish;
            }
        }
        if (st == status_$ast_eof) {
            /* 0x00E100B6-0x00E100DA: zero the rest of the partial page */
            partial = (int16_t)(0x400 - partial);
            zero_len = partial;
            network_$phys_copy(dst, NETWORK_$ZERO_PAGE_PA, partial);
            partial = 0;
            done++;
            st = status_$ok;
            goto finish;
        }

        /* 0x00E100DE-0x00E100F6: nothing yet - report the pages as null */
        if (done == 0 && partial == 0 && resp.page_cnt > 0) {
            out = ppn_array;
            *out = 0;
            done = resp.page_cnt;
            goto finish;
        }

        /* 0x00E100FA-0x00E10192: zero-fill page_cnt pages */
        zero_bytes = (int32_t)resp.page_cnt << 10;
        while (zero_bytes > 0) {
            chunk = 0x400 - (int32_t)partial;
            if (chunk > zero_bytes) {
                chunk = zero_bytes;
            }
            if (partial == 0) {
                if ((int16_t)chunk < 0x400 && done > 0) {
                    goto finish;
                }
                NETBUF_$GET_DAT(&dat);
                dst = dat;
                *out = dst >> 10;
            }
            network_$phys_copy(dst, NETWORK_$ZERO_PAGE_PA, (int16_t)chunk);
            partial = (int16_t)(partial + (int16_t)chunk);
            if (partial < 0x400) {
                dst += (uint32_t)(int32_t)(int16_t)chunk;
            } else {
                partial = 0;
                done++;
                out++;
            }
            n = (int16_t)chunk;                           /* asr.w #10, rounded */
            if (n < 0) {
                n = (int16_t)(n + 0x3FF);
            }
            start += (uint32_t)(int32_t)(int16_t)(n >> 10);
            zero_bytes -= (int32_t)(int16_t)chunk;
        }
        continue;

    wrong_reply:
        /* 0x00E10194-0x00E101C4 */
        if (data_bufs[0] != 0) {
            PKT_$DUMP_DATA(data_bufs, (int16_t)data_len);
        }
        if (resp.type == NETWORK_PAGIN_REPLY) {
            goto wait;
        }
        st = status_$network_unexpected_reply_type;
        if (seq == 1) {
            goto finish;
        }
    }

finish:
    /* 0x00E101D4-0x00E10200: take the donated buffers back */
    if (donated != 0) {
        n = (int16_t)(donated - 1);
        do {
            NETBUF_$GET_DAT(&dat);
            MMAP_$FREE(dat >> 10);
        } while (--n != -1);
    }

    /* 0x00E10204-0x00E10220: a partially filled page goes back to NETBUF */
    if (partial != 0) {
        NETBUF_$RTN_DAT(ppn_array[done] << 10);
    }

    /* 0x00E10222-0x00E1025C */
    SOCK_$CLOSE(sock);
    NETWORK_$READ_CALL_CNT = (uint16_t)(NETWORK_$READ_CALL_CNT + done);
    if (done > 1) {
        NETWORK_$RCV_READ_AHEAD = (uint16_t)(NETWORK_$RCV_READ_AHEAD + done - 1);
    }
    if (hdr_done >= 0 || done == 0) {
        *status = st;
    }
    (void)bufs_used;
    (void)zero_len;
    return done;
}
